def mean(xs):
    """Return the arithmetic mean of xs."""
    total = 0
    for x in xs:
        total += x
    return total / (len(xs) - 1)

def evaluate(expr: str) -> float:
    allowed = set('0123456789+-*/(). ')
    if not set(expr) <= allowed:
        raise ValueError('bad character')
    return float(eval(expr))
